import React, { useState, useEffect, useRef } from 'react';
import { firestore, auth } from '../firebase';
import { collection, addDoc, query, orderBy, where, onSnapshot, setDoc, doc, serverTimestamp, getDoc } from 'firebase/firestore';
import { useParams, useNavigate } from 'react-router-dom';
import TopBar from '../components/TopBar';
import './ChatPage.css';

const ChatPage = () => {
  const { chatId } = useParams(); // Получаем chatId из URL
  const navigate = useNavigate();
  const currentUser = auth.currentUser;
  
  // Преобразуем строку в массив и сортируем для единообразия
  const chatUsersArray = chatId.split('_').sort();
  const fixedChatId = chatUsersArray.join('_');
  
  const [messages, setMessages] = useState([]);
  const [input, setInput] = useState('');
  const [partnerName, setPartnerName] = useState('Собеседник');
  const messagesEndRef = useRef(null);
  
  useEffect(() => {
    // Проверяем, что текущий пользователь является участником этого чата
    if (!chatUsersArray.includes(currentUser.uid)) {
      console.error("Текущий пользователь не является участником этого чата");
      navigate('/chats');
      return;
    }
    
    // Находим ID второго участника чата
    const partnerId = chatUsersArray.find(id => id !== currentUser.uid);
    
    // Получаем имя собеседника из Firestore
    const fetchPartnerInfo = async () => {
      try {
        const partnerDoc = await getDoc(doc(firestore, 'users', partnerId));
        if (partnerDoc.exists()) {
          const partnerData = partnerDoc.data();
          setPartnerName(partnerData.name || partnerData.displayName || 'Собеседник');
        }
      } catch (error) {
        console.error("Ошибка при получении данных собеседника:", error);
      }
    };
    
    fetchPartnerInfo();
    
    // Загружаем сообщения для конкретного чата
    const q = query(
      collection(firestore, 'messages'),
      where('chatId', '==', fixedChatId),
      orderBy('timestamp', 'asc')
    );
        
    const unsubscribe = onSnapshot(q, (snapshot) => {
      setMessages(snapshot.docs.map(doc => ({
        id: doc.id,
        ...doc.data()
      })));
    });
    
    return () => unsubscribe();
  }, [fixedChatId, currentUser.uid, chatUsersArray, navigate]);
  
  const handleSend = async () => {
    if (input.trim()) {
      try {
        // Подготавливаем данные сообщения
        const newMessage = {
          text: input.trim(),
          sender: currentUser.uid,
          timestamp: serverTimestamp(),
          displayName: currentUser.displayName || 'Пользователь',
          chatId: fixedChatId,
          chatUsers: chatUsersArray,
        };
        
        // Добавляем сообщение в коллекцию messages
        await addDoc(collection(firestore, 'messages'), newMessage);
        
        // Обновляем (или создаём) документ в коллекции chats
        const chatDocRef = doc(firestore, 'chats', fixedChatId);
        await setDoc(chatDocRef, {
          participants: chatUsersArray,
          lastMessage: input.trim(),
          timestamp: serverTimestamp()
        }, { merge: true });
        
        setInput('');
      } catch (error) {
        console.error("Ошибка при отправке сообщения:", error);
      }
    }
  };
  
  const handleKeyPress = (e) => {
    if (e.key === 'Enter' && !e.shiftKey) {
      e.preventDefault();
      handleSend();
    }
  };
  
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);
  
  return (
    <div className="chat-page">
      <TopBar />
      <div className="chat-container">
        <div className="chat-header neon-border">
          <h2><i className="fas fa-comments"></i> Чат с {partnerName}</h2>
        </div>
        <div className="chat-messages">
          {messages.map((msg) => (
            <div 
              key={msg.id}
              className={`message ${msg.sender === currentUser.uid ? 'sent' : 'received'}`}
            >
              <div className="message-bubble glow-on-hover">
                <div className="message-author">
                  {msg.displayName || 'Аноним'}
                </div>
                {msg.text}
              </div>
            </div>
          ))}
          <div ref={messagesEndRef} />
        </div>
        <div className="chat-input-container glassmorphism">
          <textarea 
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onKeyPress={handleKeyPress}
            placeholder="Напишите сообщение..."
            rows="1"
            className="message-input"
          />
          <button onClick={handleSend} className="send-button pulse-on-hover">
            <i className="fas fa-paper-plane"></i>
          </button>
        </div>
      </div>
    </div>
  );
};

export default ChatPage;