import React, { useState, useEffect } from 'react';
import TopBar from '../components/TopBar';
import './ChatsPage.css';
import { firestore, auth } from '../firebase';
import { collection, query, where, orderBy, onSnapshot, getDocs } from 'firebase/firestore';
import { Link } from 'react-router-dom';

const ChatsPage = () => {
    const [chats, setChats] = useState([]);
    const [chatUsers, setChatUsers] = useState({});
    const currentUserId = auth.currentUser.uid;

    useEffect(() => {
        // Ищем все чаты, в которых участвует текущий пользователь
        const chatsQuery = query(
            collection(firestore, 'chats'),
            where('participants', 'array-contains', currentUserId)
        );

        const unsubscribe = onSnapshot(chatsQuery, async (chatsSnapshot) => {
            // Преобразуем снимок в массив данных
            const chatsData = chatsSnapshot.docs.map(doc => ({
                chatId: doc.id,
                ...doc.data()
            }));

            // Получаем информацию о пользователях для отображения имен
            const userIds = new Set();
            chatsData.forEach(chat => {
                chat.participants.forEach(userId => {
                    if (userId !== currentUserId) {
                        userIds.add(userId);
                    }
                });
            });

            // Получаем данные о пользователях для отображения имен
            const usersData = {};
            const usersPromises = Array.from(userIds).map(async (userId) => {
                const userDoc = await getDocs(query(
                    collection(firestore, 'users'),
                    where('uid', '==', userId)
                ));
                
                if (!userDoc.empty) {
                    const userData = userDoc.docs[0].data();
                    usersData[userId] = {
                        name: userData.name || 'Пользователь',
                        photo: userData.photos && userData.photos.length > 0 
                            ? userData.photos[0] 
                            : null
                    };
                } else {
                    // Если данные пользователя не найдены, используем ID как имя
                    usersData[userId] = { name: userId.substring(0, 8) + '...', photo: null };
                }
            });

            await Promise.all(usersPromises);
            setChatUsers(usersData);
            setChats(chatsData);
        });

        return () => unsubscribe();
    }, [currentUserId]);

    return (
        <div className="chats-page-container">
            <TopBar />
            <div className="chats-content">
                <div className="chats-header">
                    <h2>Чаты</h2>
                </div>
                <div className="chats-list">
                    {chats.map(chat => {
                        // Находим ID собеседника (не текущего пользователя)
                        const partnerId = chat.participants.find(id => id !== currentUserId);
                        const partner = chatUsers[partnerId] || { name: 'Пользователь' };

                        return (
                            <Link key={chat.chatId} to={`/chat/${chat.chatId}`} className="chat-item">
                                <div className="chat-item-avatar">
                                    {partner.photo ? (
                                        <img 
                                            src={partner.photo.startsWith('http') ? partner.photo : `http://localhost:5000${partner.photo}`} 
                                            alt={partner.name}
                                            style={{width: '100%', height: '100%', borderRadius: '50%', objectFit: 'cover'}}
                                        />
                                    ) : (
                                        <div style={{width: '100%', height: '100%', backgroundColor: '#ccc', borderRadius: '50%'}}></div>
                                    )}
                                </div>
                                <div className="chat-item-info">
                                    <h3 className="chat-item-name">{partner.name}</h3>
                                    <p className="chat-item-last-message">{chat.lastMessage}</p>
                                </div>
                            </Link>
                        );
                    })}
                    {chats.length === 0 && (
                        <div className="no-chats">
                            <span>У вас пока нет чатов. Начните общение!</span>
                        </div>
                    )}
                </div>
            </div>
        </div>
    );
};

export default ChatsPage;