import React from 'react';
import { useSwipeable } from 'react-swipeable';
import { FiHeart, FiX } from 'react-icons/fi';
import { useNavigate } from 'react-router-dom';
import { auth } from '../firebase';
import './DatingCard.css';

const DatingCard = ({ user, onSwipe }) => {
    const navigate = useNavigate();
    const currentUserId = auth.currentUser.uid;
    
    const handlers = useSwipeable({
        onSwipedLeft: () => onSwipe('left'),
        onSwipedRight: () => onSwipe('right'), // Оставляем свайп вправо для смахивания карточки, если нужно
        trackMouse: true
    });
    
    if (!user) return null;
    
    const getPhotoUrl = () => {
        if (!user.photos || user.photos.length === 0) return '';
        return user.photos[0].startsWith('http')
            ? user.photos[0]
            : `http://localhost:5000${user.photos[0]}`; // Исправлена интерполяция URL
    };
    
    const handleLikeClick = () => {
        onSwipe('right'); // Все еще вызываем смахивание, если хотите анимацию смахивания
        
        // Создаем chatId из ID обоих пользователей, отсортированных для единообразия
        const participants = [currentUserId, user.uid].sort();
        const chatId = participants.join('_');
        
        navigate(`/chat/${chatId}`); // Переход к чату при нажатии на лайк
    };
    
    return (
        <div {...handlers} className="dating-card">
            <div className="photo-container">
                <div
                    className="main-photo"
                    style={{
                        backgroundImage: `url(${getPhotoUrl()})`, // Исправлена интерполяция URL
                        backgroundSize: 'cover',
                        backgroundPosition: 'center'
                    }}
                />
            </div>
            
            <div className="profile-info">
                <h2>{user.name}, {user.age}</h2>
                <p>{user.city}</p>
                <div className="interests-container">
                    {user.interests?.split(',').map((interest, index) => (
                        <span key={index} className="interest-pill">{interest.trim()}</span>
                    ))}
                </div>
            </div>
            
            <div className="action-buttons">
                <button className="dislike-btn" onClick={() => onSwipe('left')}>
                    <FiX size={28} />
                </button>
                <button className="like-btn" onClick={handleLikeClick}> {/* Используем handleLikeClick */}
                    <FiHeart size={28} />
                </button>
            </div>
        </div>
    );
};

export default DatingCard;