import React, { useState, useEffect } from 'react';
import { auth, firestore } from '../firebase';
import { doc, setDoc, getDoc } from 'firebase/firestore';
import axios from 'axios';
import TopBar from '../components/TopBar';
import './ProfilePage.css';

const ProfilePage = () => {
    const [formData, setFormData] = useState({
        name: '',
        age: '',
        city: '',
        gender: '',
        interests: '',
        photo: ''
    });
    const [uploading, setUploading] = useState(false);

    useEffect(() => {
        const loadProfile = async () => {
            const user = auth.currentUser;
            if (user) {
                const docRef = doc(firestore, 'users', user.uid);
                const docSnap = await getDoc(docRef);
                if (docSnap.exists()) {
                    const userData = docSnap.data();
                    setFormData({
                        ...userData,
                        photo: userData.photos?.[0] || ''
                    });
                }
            }
        };
        loadProfile();
    }, []);

    const handleFileUpload = async (file) => {
        setUploading(true);
        try {
            const formData = new FormData();
            formData.append('photo', file);
            const userId = auth.currentUser.uid;
            const response = await axios.post(`http://localhost:5000/api/upload/${userId}`, formData, {
                headers: { 'Content-Type': 'multipart/form-data' }
            });
            const filePath = response.data.filePath;
            setFormData(prev => ({ ...prev, photo: filePath }));
        } catch (error) {
            console.error('Ошибка загрузки фото на сервер:', error);
            alert('Ошибка загрузки фото! Попробуйте еще раз.');
        }
        setUploading(false);
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        try {
            await setDoc(doc(firestore, 'users', auth.currentUser.uid), {
                ...formData,
                uid: auth.currentUser.uid,
                email: auth.currentUser.email,
                timestamp: new Date(),
                photos: formData.photo ? [formData.photo] : []
            }, { merge: true });
            alert('Профиль сохранен!');
        } catch (error) {
            console.error('Ошибка сохранения профиля:', error);
        }
    };

    return (
        <div className="profile-page">
            <TopBar />
            <div className="profile-container">
                <h2>Редактирование профиля</h2>
                <form onSubmit={handleSubmit}>
                    <div className="form-section">
                        <div className="form-group">
                            <label>Имя:</label>
                            <input type="text" value={formData.name} onChange={(e) => setFormData({ ...formData, name: e.target.value })} required />
                        </div>
                        <div className="form-group">
                            <label>Возраст:</label>
                            <input type="number" value={formData.age} onChange={(e) => setFormData({ ...formData, age: e.target.value })} min="18" max="100" required />
                        </div>
                        <div className="form-group">
                            <label>Город:</label>
                            <input type="text" value={formData.city} onChange={(e) => setFormData({ ...formData, city: e.target.value })} required />
                        </div>
                        <div className="form-group">
                            <label>Пол:</label>
                            <select value={formData.gender} onChange={(e) => setFormData({ ...formData, gender: e.target.value })} required>
                                <option value="">Выберите</option>
                                <option value="male">Мужской</option>
                                <option value="female">Женский</option>
                            </select>
                        </div>
                        <div className="form-group">
                            <label>Интересы:</label>
                            <input type="text" value={formData.interests} onChange={(e) => setFormData({ ...formData, interests: e.target.value })} placeholder="спорт, музыка, кино" />
                        </div>
                    </div>
                    <div className="form-section">
                        <h3>Фотография профиля</h3>
                        <label className={`upload-box ${uploading ? 'disabled' : ''}`}>
                            <input type="file" onChange={(e) => handleFileUpload(e.target.files[0])} accept="image/*" disabled={uploading} />
                            {uploading ? 'Загрузка...' : formData.photo ? 'Заменить фото' : '+'}
                            {formData.photo && <div className="photo-preview" style={{ backgroundImage: `url(${formData.photo})` }} />}
                        </label>
                    </div>
                    <button type="submit" className="save-button">Сохранить изменения</button>
                </form>
            </div>
        </div>
    );
};

export default ProfilePage;
